// TypeScript Version: 4.1

/* eslint-disable @typescript-eslint/unified-signatures */

/// <reference types="@stdlib/types"/>

import { DataTypeMap, TypedDataTypeMap, Order } from '@stdlib/types/ndarray';
import ArrayBuffer = require( '@stdlib/array/buffer' );

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Array order (either 'row-major' (C-style) or 'column-major' (Fortran-style)).
	*/
	order?: Order;

	/**
	* Boolean indicating whether an array should be read-only (default: false).
	*/
	readonly?: boolean;
}

/**
* Interface for the function returned by the factory method.
*/
interface GenericTensor0D {
	/**
	* Creates a zero-dimensional ndarray.
	*
	* @returns zero-dimensional ndarray
	*/
	(): DataTypeMap<number>['generic'];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param value - scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*/
	<T = unknown>( value: T, options?: Options ): DataTypeMap<T>['generic'];
}

/**
* Interface for the function returned by the factory method.
*/
interface TypedTensor0D<T extends keyof TypedDataTypeMap> {
	/**
	* Creates a zero-dimensional ndarray.
	*
	* @returns zero-dimensional ndarray
	*/
	(): TypedDataTypeMap[T];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*/
	( buffer: ArrayBuffer, options?: Options ): TypedDataTypeMap[T];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param value - scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*/
	( value: unknown, options?: Options ): TypedDataTypeMap[T];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*/
	( buffer: ArrayBuffer, byteOffset: number, options?: Options ): TypedDataTypeMap[T];
}

/**
* Interface for creating a zero-dimensional ndarray.
*/
interface Tensor0D {
	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param dtype - data type
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d();
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 'float32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 'float32', {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*/
	<T = number, U extends keyof DataTypeMap<T> = 'float64'>( dtype?: U, options?: Options ): DataTypeMap<T>[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param dtype - data type (default: 'float64')
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 8 );
	* var arr = tensor0d( buf );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 4 );
	* var arr = tensor0d( buf, 'float32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 4 );
	* var arr = tensor0d( buf, 'float32', {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*/
	<U extends keyof TypedDataTypeMap = 'float64'>( buffer: ArrayBuffer, dtype?: U, options?: Options ): TypedDataTypeMap[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 8 );
	* var arr = tensor0d( buf, {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*/
	<U extends keyof TypedDataTypeMap = 'float64'>( buffer: ArrayBuffer, options: Options ): TypedDataTypeMap[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param value - scalar value
	* @param dtype - data type
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 1.0 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 1, 'int32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'int32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 1, 'int32', {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'int32'
	*/
	<T = unknown, U extends keyof DataTypeMap<T> = 'float64'>( value: T, dtype?: U, options?: Options ): DataTypeMap<T>[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param value - scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = tensor0d( 1.0, {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*/
	<T = unknown, U extends keyof DataTypeMap<T> = 'float64'>( value: T, options: Options ): DataTypeMap<T>[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param dtype - data type (default: 'float64')
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = tensor0d( buf, 8 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = tensor0d( buf, 8, 'float32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = tensor0d( buf, 8, 'float32', {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*/
	<U extends keyof TypedDataTypeMap = 'float64'>( buffer: ArrayBuffer, byteOffset?: number, dtype?: U, options?: Options ): TypedDataTypeMap[U];

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = tensor0d( buf, 8 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = tensor0d( buf, 8, {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*/
	<U extends keyof TypedDataTypeMap = 'float64'>( buffer: ArrayBuffer, byteOffset: number, options: Options ): TypedDataTypeMap[U];

	/**
	* Returns a function for creating a zero-dimensional ndarray.
	*
	* @param dtype - data type
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray by default
	* @param options.order - default memory layout (either row-major or column-major)
	* @returns function for creating a tensor0d
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var Float32Tensor0D = tensor0d.factory( 'float32' );
	*
	* var arr = new Float32Tensor0D( 1 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var Float32Tensor0D = tensor0d.factory( 'float32' );
	*
	* var arr = new Float32Tensor0D( 3 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var Float32Tensor0D = tensor0d.factory( 'float32' );
	*
	* var buf = new ArrayBuffer( 4 );
	* var arr = new Float32Tensor0D( buf );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var Float32Tensor0D = tensor0d.factory( 'float32' );
	*
	* var buf = new ArrayBuffer( 8 );
	* var arr = new Float32Tensor0D( buf, 4 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*/
	factory<T extends keyof TypedDataTypeMap>( dtype: T, options?: Options ): TypedTensor0D<T>;

	/**
	* Returns a function for creating a zero-dimensional ndarray.
	*
	* @param dtype - data type
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray by default
	* @param options.order - default memory layout (either row-major or column-major)
	* @returns function for creating a tensor0d
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var GenericTensor0D = tensor0d.factory( 'generic' );
	*
	* var arr = new GenericTensor0D( 1 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'generic'
	*/
	factory( dtype: 'generic', options?: Options ): GenericTensor0D;
}

/**
* Creates a zero-dimensional ndarray.
*
* @param arg - scalar or buffer
* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
* @param dtype - data type (default: 'float64')
* @param options - function options
* @param options.readonly - boolean indicating whether to return a read-only ndarray
* @param options.order - memory layout (either row-major or column-major)
* @returns zero-dimensional ndarray
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d();
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d( 1.0 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = tensor0d( 1.0, 'float32' );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 12 );
* var arr = tensor0d( buf, 8, 'int32' );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'int32'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = tensor0d( buf, 8, 'int32', {} );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'int32'
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var Float32Tensor0D = tensor0d.factory( 'float32' );
*
* var arr = new Float32Tensor0D( 1.0 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*/
declare var tensor0d: Tensor0D;


// EXPORTS //

export = tensor0d;
